export function adoptComponentChildren(
	root: Root,
	children: Child[],
	nodes: readonly Node[],
	parentInstance: AnyComponentInstance | undefined,
	parentScope: EffectScope,
	start = 0,
	end = nodes.length
): Mounted[] | undefined {
	const direct = adoptStaticChildren(
		root,
		children,
		nodes,
		parentInstance,
		parentScope,
		start,
		end
	);
	if (direct) return direct;
	const opening = nodes[start];
	if (!(opening instanceof Comment) || !isChildRangeOpening(opening.data)) return undefined;
	const closingIndex = closingMarkerIndex(nodes, start, opening.data, end);
	if (closingIndex !== end - 1) return undefined;
	const adopted = adoptStaticChildren(
		root,
		children,
		nodes,
		parentInstance,
		parentScope,
		start + 1,
		closingIndex
	);
	if (!adopted) return undefined;
	opening.remove();
	const closing = nodes[closingIndex];
	closing?.parentNode?.removeChild(closing);
	return adopted;
}

/** Identifies a stable dynamic range or the compact ordered compiler-direct range. */
export function isChildRangeOpening(value: string): boolean {
	return value === 'x' || value.startsWith('exact:dynamic:');
}

/** Performs the adopt static children range domain operation. */
export function adoptStaticChildrenRange(
	root: Root,
	children: Child[],
	nodes: readonly Node[],
	parentInstance: AnyComponentInstance | undefined,
	parentScope: EffectScope,
	requireAll: boolean,
	start = 0,
	end = nodes.length
): { mounts: Mounted[]; next: number } | undefined {
	const mounts: Mounted[] = [];
	let cursor = start;
	for (const child of children) {
		if (child === null || child === undefined || child === false || child === true) continue;
		const keyedReceipt = readCompiledKeyedChildReceipt(child);
		if (keyedReceipt) {
			const opening = nodes[cursor];
