								? requireStructuralBoundaryCapability().adoptActivityReceipt(
										root,
										activityReceipt,
										nodes,
										cursor,
										parentInstance,
										parentScope,
										end,
										adoptStaticChildren
									)
								: unsafeHtmlReceipt
									? requireUnsafeHtmlDomCapability().adopt(
											root,
											unsafeHtmlReceipt,
											nodes,
											cursor,
											parentScope,
											end
										)
									: suspenseReceipt
										? requireStructuralBoundaryCapability().adoptSuspenseReceipt(
												root,
												suspenseReceipt,
												nodes,
												cursor,
												parentInstance,
												parentScope,
												end,
												adoptStaticChildren
											)
										: renderProgramReceipt
											? withTreeDepth(root, () => {
													countDomWork(root);
													return adoptCompiledRenderProgram(
														root,
														child,
														nodes,
														cursor,
														parentInstance,
														createEffectScope(parentScope),
														end,
														(values, childNodes, owner, scope, childCursor, childEnd) =>
															adoptStaticChildren(
																root,
																[...values],
																childNodes,
																owner,
																scope,
																childCursor,
																childEnd
															)
													);
