/** @vitest-environment jsdom */
import { describe, expect, it } from 'vitest';
import type { ExactRenderProgram } from '@exactjs/core/runtime/render';
import { claimCompiledRenderProgram } from './render-program-claims.js';

const program = {
	version: 8, id: 'adjacent-text', namespace: 'html', directClaims: true,
	template: '<p><!---->first<!----> · <!---->second<!----></p>',
	wire: [['p', 'html', 1, 2], [[3, 0, 0, 'a'], [3, 1, 1, 'b']], []]
} satisfies ExactRenderProgram;

describe('length-delimited text hydration experiment', () => {
	it.each(['', 'a', '🚀', 'a\r\nb', '<&>'])('retains independent text boundaries for %j', (value) => {
		const normalized = value.replace(/\r\n?/g, '\n').replaceAll('\0', '\uFFFD');
		const escaped = value.replaceAll('&', '&amp;').replaceAll('<', '&lt;');
		const root = document.createElement('p');
		root.innerHTML = `<!--t:a:${normalized.length.toString(36)}-->${escaped} · <!--t:b:4-->tail`;
		const claimed = claimCompiledRenderProgram(program, root, 'ssr');
		expect(claimed).toBeDefined();
		const first = claimed!.slotNodes[0] as Text;
		const second = claimed!.slotNodes[1] as Text;
		expect(first.data).toBe(normalized);
		expect(second.data).toBe('tail');
		first.data = 'changed';
		expect(root.textContent).toBe('changed · tail');
		second.data = '';
		expect(root.textContent).toBe('changed · ');
		expect(root.childNodes).toHaveLength(3);
	});

	it.each(['-1', '!', 'zzzzzzzzzzzzzzzzzz', '9'])('rejects an invalid or oversized text extent %s', (length) => {
		const root = document.createElement('p');
		root.innerHTML = `<!--t:a:${length}-->a`;
		const before = root.innerHTML;
		expect(claimCompiledRenderProgram(program, root, 'ssr')).toBeUndefined();
		expect(root.innerHTML).toBe(before);
	});
});

